```python
def tim(a, x):
    trai, phai = 0, len(a) - 1
    while trai <= phai:
        giua = (trai + phai) // 2
        if a[giua] == x:
            return giua
        elif a[giua] < x:
            trai = giua
        else:
            phai = giua - 1
    return -1

